/* __VOICE_DATA_BEGIN__ */
// 语音数据由 inject_voice.py 注入；要改请重跑脚本，不要手改下面这行。
window.__PRIESTESS_VOICES__ = [
  "data:audio/wav;base64,",
];
/* __VOICE_DATA_END__ */
/**
 * dsh-priestess-companion — Client half.
 *
 * 普瑞赛斯悬浮在 DSH 网页最上层，身旁一行浅白色的余额。她可以被拖到任何地方，
 * 松手后位置会被记住，刷新页面仍在原处。
 *
 * 她住在 `shell.overlay`：整帧最上层的浮动层，天生给徽标、胶囊这类东西准备的，
 * 所以聊天框、侧栏、输入框都盖不住她。那一层**本身是点击穿透的**，只有我们这个
 * 节点重新打开了指针事件——不拖她的时候，她挡不住下面的应用。
 *
 * 三条规矩：
 *   1. **数字只在宿主那里取**（浏览器拿不到账号凭据），这里只负责显示与何时再问。
 *   2. **图片绝不拉伸**：宽度由配置给，高度一律 auto。容器**没有背景**——她是抠图，
 *      垫一层底色就等于把抠图白抠了。
 *   3. 每一种失败都要看得见：没登录、远端失败、请求没成，各有各的样子。
 */

// 第一手的自我地址：经典 <script> 加载时 document.currentScript 就指着自己。
// （type="module" 加载时它是 null，所以在 watchOwnBundle 里还有资源列表与启动载荷两条退路。）
try {
  window.__PRIESTESS_SELF_SRC__ = (document.currentScript && document.currentScript.src) || null
} catch { /* 取不到就走别的路 */ }

// 模块一被求值就报一声。这一条的意义是：**只要它出现，就证明浏览器里跑的是新版**；
// 报告文件里看不到它，说明页面加载的还是旧模块，那问题就不在代码而在缓存。
// 默认关闭：把 window.__PRIESTESS_DIAGNOSTIC__ 设成 true 才会上报（排查时用）。
try {
  if (window.__PRIESTESS_DIAGNOSTIC__ === true) {
    fetch('/dsh-startup-voice/report', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        outcome: 'pc-module-loaded',
        name: 'companion-b9',
        detail: `src=${String(window.__PRIESTESS_SELF_SRC__).slice(0, 120)}`,
        volume: null,
        readyState: null,
      }),
    }).catch(() => {})
  }
} catch { /* 上报失败不影响挂件 */ }

window.__ModuleLoader__.load({
  id: 'dsh-priestess-companion',
  factory(require) {
    const React = require('react')
    const h = React.createElement

    const BASE = '/dsh-priestess-companion'
    const STATE_URL = `${BASE}/state.json`
    const SLOT = 'shell.overlay'
    const ROW_ID = 'priestess-companion'
    /** 模块 id，与外面 load({id}) 保持一致——用它把自己从资源列表里认出来。 */
    const MODULE_ID = 'dsh-priestess-companion'
    /** 自己盯自己源码的间隔（毫秒）；设为 0 就关掉自动刷新。 */
    const SELF_CHECK_MS = 5000
    /** 超过这么多像素才算拖动，否则当成点击。鼠标的抖动通常是 1–2 像素。 */
    const DRAG_THRESHOLD = 4
    /** 构建标记：诊断上报时带上它，用来分辨"浏览器里跑的是哪一版"。 */
    const BUILD_TAG = 'companion-b9'
    /** 诊断上报开关。默认**关**：它会往 dsh-startup-voice 的报告文件里写东西，
     *  污染那边设置页显示的"最近一次播放结果"。排查问题时再临时打开。 */
    const DIAGNOSTIC = false
    /** 位置存在浏览器本地：刷新页面还在，且不跨设备同步——这是"这台机器上她站哪儿"。 */
    const POS_KEY = 'dsh-priestess-companion:position'

    const TEXT = {
      zh: {
        loading: '——',
        signedOut: '未登录',
        unavailable: '读不到余额',
        failed: '连接失败',
        refresh: '刷新余额',
        refreshing: '正在刷新…',
        credit: '充值余额',
        bonus: '赠送余额',
        sourceAccount: '来源：DSH 账号',
        sourceUrl: '来源：自定义接口',
        sourceFixed: '来源：固定值',
        updated: '更新于',
        hint: '按住她可以拖动',
        justNow: '刚刚',
        secondsAgo: (n) => `${n} 秒前`,
        minutesAgo: (n) => `${n} 分钟前`,
        hoursAgo: (n) => `${n} 小时前`,
      },
      en: {
        loading: '——',
        signedOut: 'Signed out',
        unavailable: 'No balance',
        failed: 'Offline',
        refresh: 'Refresh balance',
        refreshing: 'Refreshing…',
        credit: 'Credit',
        bonus: 'Bonus',
        sourceAccount: 'Source: DSH account',
        sourceUrl: 'Source: custom API',
        sourceFixed: 'Source: fixed value',
        updated: 'updated',
        hint: 'Drag her to move',
        justNow: 'just now',
        secondsAgo: (n) => `${n}s ago`,
        minutesAgo: (n) => `${n}m ago`,
        hoursAgo: (n) => `${n}h ago`,
      },
    }

    /** @returns 当前语言的文案表，缺的回落中文。 */
    function strings() {
      let locale = 'zh'
      try {
        locale = String((navigator && navigator.language) || 'zh').toLowerCase()
      } catch { /* 没有 navigator 就用默认 */ }
      return locale.startsWith('en') ? { ...TEXT.zh, ...TEXT.en } : TEXT.zh
    }

    /** @returns 是否该关掉动画（系统偏好）。 */
    function reducedMotion() {
      try {
        return window.matchMedia('(prefers-reduced-motion: reduce)').matches
      } catch {
        return false
      }
    }

    /** 语音音量 0–1。想改就改这里（客户端半：改完**刷新页面**生效）。 */
    const VOICE_VOLUME = 0.9

    /** 点她时说的那句话，以及它停留多久（毫秒）。 */
    const LINE_TEXT = '博士，不准忘记我。'
    const LINE_MS = 3200

    /**
     * 可播的语音池。
     *
     * 数据由 `inject_voice.py` 注入到文件顶部的 `window.__PRIESTESS_VOICES__`——
     * 为什么不走宿主路由：宿主半的代码改了**必须重启 DSH 进程**才生效（模块缓存），
     * 而把音频内联进客户端是热更的，改完立刻能响。
     * 代价是音频数据跟着页面走（本机 206 KB 的 wav → 约 275 KB 的 base64），
     * 以后语音多了就该换成"宿主扫目录 + 提供列表"的做法，那需要重启一次。
     * @returns 可直接喂给 Audio 的地址数组；没有就返回空数组。
     */
    function voicePool() {
      const injected = window.__PRIESTESS_VOICES__
      if (!Array.isArray(injected)) return []
      return injected.filter((item) => typeof item === 'string' && item !== '')
    }

    /**
     * 随机播一条语音。
     * @param ref - 用来记住当前正在播的那条，连点时不叠音。
     */
    function playVoice(ref) {
      const pool = voicePool()
      if (pool.length === 0) return
      const src = pool[Math.floor(Math.random() * pool.length)]
      try {
        if (ref.current !== null) {
          ref.current.pause()
          ref.current = null
        }
        const audio = new Audio(src)
        audio.volume = VOICE_VOLUME
        ref.current = audio
        // 播放失败不该有任何可见后果（比如被策略拦下）：静默即可。
        void audio.play().catch(() => {})
      } catch { /* 构造 Audio 失败也不影响别的 */ }
    }

    /**
     * 诊断上报：把**只有页面内部知道**的事实写回宿主，落进文件，我再读文件。
     *
     * 借的是 `dsh-startup-voice` 的 `/report` 路由（它本来就干这个：POST 一条 JSON，
     * 宿主 append 到 `$DSH_HOME/dsh-startup-voice/play-report.jsonl`）。
     * 为什么非要有这条通道：「灰影看不见、点了没声」这件事的答案全在浏览器里，
     * 宿主从外面看不见；不回报就只能靠猜。上报是 best-effort，失败绝不影响挂件。
     * @param outcome - 事件名（会显示在报告文件里）。
     * @param detail - 一句话细节，别超过 180 字（宿主会截断）。
     */
    function probe(outcome, detail) {
      if (DIAGNOSTIC !== true) return
      try {
        void fetch('/dsh-startup-voice/report', {
          method: 'POST',
          credentials: 'same-origin',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            outcome,
            name: BUILD_TAG,
            detail: String(detail).slice(0, 180),
            volume: null,
            readyState: null,
          }),
        }).catch(() => {})
      } catch { /* 上报失败不影响挂件 */ }
    }

    /**
     * 找出"我自己这个模块"的地址。
     *
     * 浏览器把每个取过的资源都记在 resource timing 里，包括这个客户端模块，
     * 所以按模块 id 匹配就能认出自己——不需要宿主额外给一个版本接口。
     * @returns 地址，或 null（认不出来就干脆不自动刷新，不要瞎猜）。
     */
    function findOwnBundleUrl() {
      try {
        // 三来源依次兜底：加载时抓到的 script src → 资源计时列表 → 启动载荷里的字符串。
        const captured = window.__PRIESTESS_SELF_SRC__
        if (typeof captured === 'string' && captured !== '') return captured
        const entries = performance.getEntriesByType('resource')
        for (const entry of entries) {
          const name = entry && entry.name
          if (typeof name === 'string' && name.includes(MODULE_ID) && name.includes('.js')) return name
        }
        // 退路：启动载荷里通常也写着模块地址，扫一遍字符串。
        const boot = window.__DSH_BOOT__
        if (boot !== undefined && boot !== null) {
          const text = JSON.stringify(boot)
          const hit = text.match(new RegExp(`[^"']*${MODULE_ID}[^"']*\\.js[^"']*`))
          if (hit !== null) return hit[0]
        }
      } catch { /* 认不出就不刷新，绝不影响挂件本身 */ }
      return null
    }

    /** @returns 一段廉价的文本指纹（长度 + djb2），够判断"变没变"。 */
    function fingerprint(text) {
      let hash = 5381
      for (let i = 0; i < text.length; i += 1) hash = ((hash << 5) + hash + text.charCodeAt(i)) | 0
      return `${text.length}:${hash}`
    }

    /** @returns 焦点是否在输入框/可编辑区里——刷新会把没发出去的话吃掉，所以这种时候推迟。 */
    function isTyping() {
      try {
        const el = document.activeElement
        if (el === null || el === undefined) return false
        return el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable === true
      } catch {
        return false
      }
    }

    /**
     * 自己盯自己：源码一变就刷新页面。
     *
     * 为什么需要它：宿主半的代码改了要重启进程、客户端半的改动要刷新页面才能生效，
     * 而"每次改完都让博士按一次 F5"很烦。这个轮询把最后一步自动化掉。
     * 只有**认得出自己的地址**时才启动；查不到就安静地什么都不做。
     * @returns 清理函数。
     */
    function watchOwnBundle() {
      if (!(SELF_CHECK_MS > 0)) return () => {}
      const url = findOwnBundleUrl()
      if (url === null) return () => {}
      let baseline = null
      const tick = () => {
        if (document.hidden === true) return
        void fetch(url, { cache: 'no-store' }).then(
          (response) => response.text(),
          () => '',
        ).then((text) => {
          if (text === '') return
          const stamp = fingerprint(text)
          if (baseline === null) {
            baseline = stamp
            return
          }
          if (stamp === baseline) return
          if (isTyping()) return   // 基线不动，下一个 tick 再试
          baseline = stamp
          window.location.reload()
        }).catch(() => {})
      }
      const timer = window.setInterval(tick, SELF_CHECK_MS)
      tick()
      return () => window.clearInterval(timer)
    }

    /**
     * 读回记住的位置。
     * @returns {x, y} 或 null（null = 用配置里的角标锚定）。
     */
    function loadPosition() {
      try {
        const raw = window.localStorage.getItem(POS_KEY)
        if (raw === null) return null
        const parsed = JSON.parse(raw)
        if (parsed !== null && typeof parsed === 'object'
          && Number.isFinite(parsed.x) && Number.isFinite(parsed.y)) {
          return { x: parsed.x, y: parsed.y }
        }
      } catch { /* 隐私模式或写坏了，就当没存过 */ }
      return null
    }

    /** @param pos - {x, y}。写失败不该影响拖动本身。 */
    function savePosition(pos) {
      try {
        window.localStorage.setItem(POS_KEY, JSON.stringify({ x: Math.round(pos.x), y: Math.round(pos.y) }))
      } catch { /* 存不下就算了，本次会话内仍然能拖 */ }
    }

    /** 把坐标夹在视口内，免得拖出屏幕再也够不着。 */
    function clampToViewport(x, y, width, height) {
      const maxX = Math.max(0, window.innerWidth - width)
      const maxY = Math.max(0, window.innerHeight - height)
      return { x: Math.min(Math.max(x, 0), maxX), y: Math.min(Math.max(y, 0), maxY) }
    }

    /**
     * 问一下图片现在的版本号。
     *
     * 为什么要在客户端做这件事：宿主给的 URL 里那个 `?v=` 一直没变，而图片路由又发
     * 了长缓存——**URL 不变 + 缓存未过期 = 浏览器根本不发请求**，换完图页面上还是旧的
     * 那张（实测踩过）。图片路由的 ETag 就是文件内容的哈希，所以拿它当版本号最可靠。
     *
     * `cache: 'no-store'` 是必须的：不带它，这次 HEAD 会直接被浏览器缓存回答，
     * 拿回来的还是旧版本号，等于没问。
     * @param url - 图片地址。
     * @returns 版本串；问不到就返回空串（此时沿用宿主给的地址）。
     */
    async function imageFingerprint(url) {
      try {
        const response = await fetch(url, { method: 'HEAD', cache: 'no-store', credentials: 'same-origin' })
        const tag = response.headers.get('etag')
        return tag === null ? '' : tag.replace(/[^0-9a-zA-Z]/g, '')
      } catch {
        return ''
      }
    }

    /**
     * 向宿主取一次状态。
     * @param force - 是否要求穿透宿主缓存。
     * @returns 响应体。
     */
    async function loadState(force) {
      const locale = (() => {
        try {
          return String((navigator && navigator.language) || 'zh-CN')
        } catch {
          return 'zh-CN'
        }
      })()
      const tz = -new Date().getTimezoneOffset() * 60
      const response = await fetch(
        `${STATE_URL}?locale=${encodeURIComponent(locale)}&tz=${tz}${force === true ? '&refresh=1' : ''}`,
        { credentials: 'same-origin', cache: 'no-store' },
      )
      if (!response.ok) throw new Error(`http-${response.status}`)
      return await response.json()
    }

    /** @returns 人类可读的相对时间。 */
    function agoText(iso, t) {
      const then = Date.parse(String(iso ?? ''))
      if (!Number.isFinite(then)) return ''
      const seconds = Math.max(0, Math.round((Date.now() - then) / 1000))
      if (seconds < 5) return t.justNow
      if (seconds < 60) return t.secondsAgo(seconds)
      if (seconds < 3600) return t.minutesAgo(Math.round(seconds / 60))
      return t.hoursAgo(Math.round(seconds / 3600))
    }

    /** 黑字 + 白晕：关键帧与伪元素没法用内联样式写，所以单独一个 style 元素。 */
    const STYLE = `
.pw-root {
  position: fixed; z-index: 30;
  display: flex; align-items: flex-start; gap: 6px;
  /* 容器不带任何背景：她是抠图，垫底色等于白抠。 */
  background: none;
  /* 所在图层是点击穿透的，这里重新打开，让她能被拖。 */
  pointer-events: auto;
  user-select: none; -webkit-user-select: none;
}
.pw-figure {
  position: relative; display: block; flex: none;
  /* 给描边与落影留出**盒内**空间。
     drop-shadow 是画在元素框**之外**的：上层容器（比如 slot 的包裹层）只要带
     overflow:hidden 或 contain:paint，影就会被整条裁掉——而 CSS 计算值照样显示
     "有 drop-shadow"，于是出现"检查全绿、肉眼什么都没有"的怪状。
     留出内边距之后，影落在自己的盒子里，随便谁裁都裁不掉。
     40px 是按"最远那层影 = 30px 模糊 + 18px 下移"留的余量。
     代价：图会因此内缩这么多像素，所以 cordis.patch.yml 里把贴边距调成了 0。 */
  padding: 40px;
}
.pw-img {
  display: block; width: 100%; height: auto;   /* 宽度由配置给，高度永远按比例 */
  -webkit-user-drag: none; user-select: none;
  cursor: grab; touch-action: none;
  /* 周围一层**灰色**阴影。用灰而不是黑：她的衣服本身就是浅色，
     黑影会在浅底上把她切出一道硬边，深底上又看不见；中灰两头都成立。

     ⚠ 这一条会被 .pw-img.pw-dim 整个覆盖掉。dim 在"状态还没取回来 / 取失败"
     时为真，那时她本来就该是灰的、半透明的——所以灰影偶尔会看不到，是设计如此。
     但要注意：如果状态一直取不回来，灰影就永远看不到。
     （注意：这段注释在一个 JS 模板字符串里，**不能出现反引号**，
       否则会把模板串提前截断，剩下的 CSS 变成一句看似合法的 JS 表达式。） */
  /* 灰色描边 + 落影。
     描边：八个方向（四正 + 四斜）各一道**零模糊**的 drop-shadow，拼成一圈贴着轮廓的
     灰线。CSS 的 drop-shadow 没有 spread 参数，这是做描边的标准办法；只走四正方向的话
     在发梢那种细处会显成一个十字，补上四道斜的才圆。
     落影：近的一层给体积，远的一层给浮起感，都用深灰（她衣服是浅色，黑边会脏）。
     注意总量——十道 filter 听着多，但这块只有 ~330×360 像素，代价可以忽略。 */
  /* 两个旋钮：以后只改这两个数，下面的 filter 一个字都不用碰。
     --pw-edge = 灰色描边的透明度（0 = 没描边，1 = 实心灰线）
     --pw-cast = 落影的透明度（远那层自动按它的 0.7 倍走，比例固定） */
  --pw-edge: 0.26;
  --pw-cast: 0.14;
  filter: drop-shadow(4px 0 0 rgba(128, 132, 142, var(--pw-edge)))
          drop-shadow(-4px 0 0 rgba(128, 132, 142, var(--pw-edge)))
          drop-shadow(0 4px 0 rgba(128, 132, 142, var(--pw-edge)))
          drop-shadow(0 -4px 0 rgba(128, 132, 142, var(--pw-edge)))
          drop-shadow(3px 3px 0 rgba(128, 132, 142, var(--pw-edge)))
          drop-shadow(-3px 3px 0 rgba(128, 132, 142, var(--pw-edge)))
          drop-shadow(3px -3px 0 rgba(128, 132, 142, var(--pw-edge)))
          drop-shadow(-3px -3px 0 rgba(128, 132, 142, var(--pw-edge)))
          drop-shadow(0 8px 14px rgba(28, 32, 42, var(--pw-cast)))
          drop-shadow(0 18px 30px rgba(28, 32, 42, calc(var(--pw-cast) * 0.7)));
}
.pw-img.pw-dragging { cursor: grabbing; }
.pw-img.pw-dim { filter: grayscale(1) brightness(0.92) opacity(0.55); }
.pw-img.pw-dim.pw-busy { opacity: 0.4; }
.pw-side {
  display: flex; flex-direction: column; align-items: flex-start; gap: 2px;
  padding: 6px 4px 6px 2px; cursor: default;
}
.pw-amount {
  display: flex; align-items: baseline; gap: 8px;
  /* 黑字，但黑里带她那身黑紫：rgba(20,12,34) 读起来仍是黑的，色调却归她。
     页面底色可深可浅，所以垫一圈**薰衣草白的柔光**当底——字仍是黑的，深色背景上也读得出。 */
  color: rgba(20, 12, 34, 0.96);
  font-size: 22px; font-weight: 700; line-height: 1.1;
  letter-spacing: 0.055em; font-variant-numeric: tabular-nums;
  text-shadow: 0 0 5px rgba(248, 244, 255, 0.95), 0 0 15px rgba(196, 178, 255, 0.70),
               0 0 30px rgba(150, 110, 220, 0.38);
  animation: pw-breathe 7s ease-in-out infinite;
  white-space: nowrap;
}
/* 菱形前缀：她的瞳孔是菱形，这也是整个插件里唯一一处刻意的"署名"。 */
.pw-diamond {
  font-size: 0.62em; font-weight: 400; line-height: 1;
  color: rgba(126, 78, 208, 0.92);
  text-shadow: 0 0 8px rgba(168, 130, 240, 0.85), 0 0 18px rgba(150, 110, 220, 0.55);
  transform: translateY(-0.12em);
}
.pw-amount.pw-muted {
  font-size: 14px; font-weight: 600; letter-spacing: 0.12em;
  color: rgba(30, 20, 50, 0.66); animation: none;
  text-shadow: 0 0 5px rgba(248, 244, 255, 0.92), 0 0 13px rgba(196, 178, 255, 0.6);
}
.pw-refresh {
  flex: none; width: 20px; height: 20px; padding: 0; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  background: rgba(250, 248, 255, 0.88);
  /* 灰色描边 + 落下的一层影：它和白底页面是靠这两样分开的，不是靠颜色。 */
  border: 1px solid rgba(118, 122, 134, 0.60);
  color: rgba(58, 32, 110, 0.92); font-size: 12px; line-height: 1;
  cursor: pointer; transition: background .15s ease, box-shadow .15s ease, border-color .15s ease;
  box-shadow: 0 2px 6px rgba(10, 14, 24, 0.26);
}
.pw-refresh:hover { background: rgba(255, 255, 255, 0.98); border-color: rgba(96, 100, 112, 0.75); box-shadow: 0 3px 10px rgba(10, 14, 24, 0.34); }
.pw-refresh:disabled { opacity: 0.5; cursor: default; }
.pw-refresh:focus-visible { outline: 2px solid rgba(126, 78, 208, 0.8); outline-offset: 2px; }
.pw-panel {
  margin-top: 4px; padding: 7px 10px; border-radius: 9px;
  font-size: 11px; line-height: 1.6; letter-spacing: 0.02em;
  /* 明细面板跟着字走：浅底的深字，贴在哪一页上都读得清。 */
  color: rgba(26, 16, 46, 0.92);
  background: rgba(248, 249, 252, 0.95);
  /* 灰色边缘 + 阴影。之前边框是淡紫的，在白底页面上等于没有边，
     整块看着就是一片平白；现在靠"灰边 + 影"把它从页面里抬起来。 */
  border: 1px solid rgba(118, 122, 134, 0.60);
  backdrop-filter: blur(4px);
  box-shadow: 0 10px 26px rgba(8, 12, 22, 0.32), 0 2px 6px rgba(8, 12, 22, 0.20);
  animation: pw-fade .18s ease;
}
.pw-panel b { font-weight: 500; color: rgba(126, 78, 208, 0.85); }
.pw-err { color: #a51f3e; }
.pw-hint {
  margin-top: 3px; font-size: 10px; letter-spacing: 0.08em;
  color: rgba(38, 24, 64, 0.55);
  text-shadow: 0 0 5px rgba(248, 244, 255, 0.9);
}
/* 点她时浮出来的那句话：垫在整块挂件的**上方**（bottom:100%），居中，
   并且 pointer-events:none —— 它盖不住任何可点的东西。 */
.pw-line {
  position: absolute; left: 0; right: 0; bottom: 100%;
  margin-bottom: 8px; text-align: center; white-space: nowrap;
  font-size: 15px; font-weight: 700; letter-spacing: 0.07em;
  color: rgba(20, 12, 34, 0.96);
  text-shadow: 0 0 6px rgba(248, 244, 255, 0.95), 0 0 18px rgba(196, 178, 255, 0.75),
               0 0 34px rgba(150, 110, 220, 0.45);
  pointer-events: none;
  animation: pw-say 3.2s ease forwards;
}
@keyframes pw-say {
  0% { opacity: 0; transform: translateY(8px); }
  12%, 74% { opacity: 1; transform: translateY(0); }
  100% { opacity: 0; transform: translateY(-8px); }
}
@keyframes pw-breathe {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.88; }
}
@keyframes pw-fade { from { opacity: 0; transform: translateY(-3px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .pw-amount, .pw-panel { animation: none; }
}
`

    /**
     * 会滚动的数字。
     *
     * 余额从 43.69 变成 41.20 时，让中间那些数字真的走过去——这是"钱在流逝"这件事
     * 唯一看得见的形态。系统偏好减少动效时直接跳到终点。
     * @param props.text - 目标文本（可能带货币符号）。
     * @returns 文本节点。
     */
    function RollingText({ text }) {
      const [shown, setShown] = React.useState(text)
      const shownRef = React.useRef(text)
      React.useEffect(() => {
        const numeric = (value) => {
          const parsed = Number(String(value).replace(/[^0-9.\-]/g, ''))
          return Number.isFinite(parsed) ? parsed : null
        }
        const to = numeric(text)
        const from = numeric(shownRef.current)
        const decimals = (String(text).split('.')[1] || '').replace(/[^0-9].*$/, '').length
        if (to === null || from === null || from === to || reducedMotion()) {
          shownRef.current = text
          setShown(text)
          return undefined
        }
        const prefix = String(text).replace(/[0-9.,\-]/g, '')
        const started = performance.now()
        let raf = 0
        const step = (now) => {
          const k = Math.min(1, (now - started) / 620)
          const eased = 1 - Math.pow(1 - k, 3)
          const value = (from + (to - from) * eased).toFixed(decimals)
          shownRef.current = prefix + value
          setShown(prefix + value)
          if (k < 1) raf = window.requestAnimationFrame(step)
        }
        raf = window.requestAnimationFrame(step)
        return () => window.cancelAnimationFrame(raf)
      }, [text])
      return h('span', null, shown)
    }

    /**
     * 挂件本体。
     * @returns 挂件节点。
     */
    function PriestessWidget() {
      const t = strings()
      const [phase, setPhase] = React.useState('loading')   // loading | ready | failed
      const [data, setData] = React.useState(null)
      const [fetchError, setFetchError] = React.useState('')
      const [busy, setBusy] = React.useState(false)
      const [hover, setHover] = React.useState(false)
      const [dragging, setDragging] = React.useState(false)
      const [pos, setPos] = React.useState(loadPosition)     // null = 用配置的角标锚定
      const [seconds, setSeconds] = React.useState(120)
      /** 图片版本号（服务端 ETag）；拿到之后拼进图片地址，换图立刻能看到。 */
      const [imageStamp, setImageStamp] = React.useState('')
      /** 点她时浮出来的那句话；带自增序号，好让每次点击都重放动画。 */
      const [line, setLine] = React.useState(null)
      /** 相对时间每分钟重算一次，否则"刚刚"会一直挂在那里。 */
      const [, setTick] = React.useState(0)

      const rootRef = React.useRef(null)
      const posRef = React.useRef(pos)
      const dragRef = React.useRef(null)
      /** 正在播的那条语音，连点时不叠音。 */
      const audioRef = React.useRef(null)
      /** 那句话的收尾定时器。 */
      const lineTimer = React.useRef(0)
      posRef.current = pos

      /** 挂载后回报一次真凶候选：**状态取回来之后**那一刻的 filter。
       *  挂载瞬间 dim 必定为真（还没数据），所以必须在 state 到手之后再问一次。 */
      const reportLook = React.useCallback(() => {
        const root = rootRef.current
        const img = root === null ? null : root.querySelector('.pw-img')
        const filter = img === null ? '(no-img)' : window.getComputedStyle(img).filter
        probe('pc-look', `ds=${filter === '' ? 0 : filter.split('drop-shadow').length - 1}`
          + `;gray=${filter.includes('grayscale') ? 1 : 0};op=${filter.includes('opacity') ? 1 : 0}`
          + `;h=${img === null ? 0 : Math.round(img.getBoundingClientRect().height)}`
          + `;w=${img === null ? 0 : Math.round(img.getBoundingClientRect().width)}`)
      }, [])

      const load = React.useCallback((force) => {
        setBusy(true)
        return loadState(force).then(
          (body) => {
            setData(body)
            setFetchError('')
            setPhase('ready')
            setBusy(false)
            setSeconds(body && body.options && typeof body.options.refreshSeconds === 'number'
              ? body.options.refreshSeconds
              : 120)
            // 每次取状态都顺手问一下图片版本：换图之后这里会变，img 的 src 跟着变，
            // 浏览器才会真的去取新的那张。
            const declared = body && body.options && typeof body.options.image === 'string'
              ? body.options.image
              : `${BASE}/image`
            void imageFingerprint(declared).then((stamp) => {
              if (stamp !== '') setImageStamp(stamp)
            })
            // 状态到手了，这时候的 filter 才是真正生效的那个——回报一次。
            window.setTimeout(reportLook, 400)
          },
          (failure) => {
            // 请求本身没成：保留上一次的数字，只在明细里说明——宁可显示旧数字加一句
            // 失败原因，也不要凭空把余额变成空白。
            setFetchError((failure && (failure.name || failure.message)) || 'unknown')
            setPhase((current) => (current === 'ready' ? 'ready' : 'failed'))
            setBusy(false)
          },
        )
      }, [])

      // 打开时取一次，之后交给定时器。
      React.useEffect(() => {
        void load(false)
      }, [load])

      React.useEffect(() => {
        if (!(seconds > 0)) return undefined
        const timer = window.setInterval(() => { void load(true) }, seconds * 1000)
        return () => window.clearInterval(timer)
      }, [load, seconds])

      React.useEffect(() => {
        const timer = window.setInterval(() => setTick((n) => n + 1), 30000)
        return () => window.clearInterval(timer)
      }, [])

      /**
       * 说出那句话：浮出来，停留几秒再收回去。
       * 每次点击都自增序号——key 一变，元素重挂，CSS 动画从头播，
       * 否则连点第二次时动画不会重来（同一段文字，React 认为没变）。
       * @param text - 要说的话。
       */
      const sayLine = React.useCallback((text) => {
        setLine((current) => ({ text, seq: (current === null ? 0 : current.seq) + 1 }))
        if (lineTimer.current !== 0) window.clearTimeout(lineTimer.current)
        lineTimer.current = window.setTimeout(() => setLine(null), LINE_MS)
      }, [])

      // 自己盯自己的源码：一变就自动刷新页面，省掉"每次都按 F5"。
      React.useEffect(() => watchOwnBundle(), [])

      // 挂载后回报一次"运行时到底长什么样"——灰影有没有生效、语音池几条、认不认得出自己。
      // 这些只有页面内部看得见，宿主从外面是黑箱。
      React.useEffect(() => {
        const root = rootRef.current
        const img = root === null ? null : root.querySelector('.pw-img')
        const filter = img === null ? '' : window.getComputedStyle(img).filter
        const shadows = filter === '' ? 0 : filter.split('drop-shadow').length - 1
        probe('pc-mounted', `shadows=${shadows};gray=${filter.includes('grayscale') ? 1 : 0}`
          + `;voice=${voicePool().length};self=${findOwnBundleUrl() === null ? 'no' : 'yes'}`
          + `;drag=${DRAG_THRESHOLD}`)
      }, [])

      // 卸载时把还在播的语音掐掉，别让声音留在卸载之后的页面上。
      React.useEffect(() => () => {
        if (audioRef.current !== null) {
          audioRef.current.pause()
          audioRef.current = null
        }
        if (lineTimer.current !== 0) window.clearTimeout(lineTimer.current)
      }, [])

      // 记住的位置要能扛住窗口变小：变窄时把她推回视野里。
      React.useEffect(() => {
        const onResize = () => {
          const root = rootRef.current
          if (root === null || posRef.current === null) return
          const rect = root.getBoundingClientRect()
          const next = clampToViewport(posRef.current.x, posRef.current.y, rect.width, rect.height)
          if (next.x !== posRef.current.x || next.y !== posRef.current.y) {
            setPos(next)
            savePosition(next)
          }
        }
        window.addEventListener('resize', onResize)
        return () => window.removeEventListener('resize', onResize)
      }, [])

      // ---- 拖拽与点击：判定区是整块挂件，但按钮与明细面板除外 ----
      const onPointerDown = (event) => {
        if (event.button !== 0) return
        // 刷新按钮、明细面板（里面还有链接）自己处理点击，不参与拖动、也不触发说话。
        const target = event.target
        if (target instanceof Element && target.closest('.pw-refresh, .pw-panel, a') !== null) return
        const root = rootRef.current
        if (root === null) return
        const rect = root.getBoundingClientRect()
        dragRef.current = {
          dx: event.clientX - rect.left,
          dy: event.clientY - rect.top,
          moved: false,
          startX: event.clientX,
          startY: event.clientY,
        }
        try {
          event.currentTarget.setPointerCapture(event.pointerId)
        } catch { /* 捕获失败也还能拖，只是手指移出元素时会断 */ }
        setDragging(true)
      }

      const onPointerMove = (event) => {
        const drag = dragRef.current
        const root = rootRef.current
        if (drag === null || root === null) return
        if (!drag.moved) {
          // **必须先过一道阈值**：鼠标按下到松开之间必然抖动 1–2 像素，只要收到任何
          // pointermove 就判成拖动的话，每一次点击都会被吃掉（语音与台词因此从不触发）。
          const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY)
          if (distance < DRAG_THRESHOLD) return
          drag.moved = true
        }
        const next = clampToViewport(
          event.clientX - drag.dx,
          event.clientY - drag.dy,
          root.offsetWidth,
          root.offsetHeight,
        )
        setPos(next)
      }

      const endDrag = () => {
        const drag = dragRef.current
        dragRef.current = null
        setDragging(false)
        if (drag === null) return
        // 只有真的动过才落盘：点一下不该改写记住的位置。
        if (drag.moved) {
          if (posRef.current !== null) savePosition(posRef.current)
          return
        }
        // 没动过 = 点了一下她 → 随机播一条语音，并说出那句话。
        // 复用拖拽状态机里的 moved，省得再判断一次"是点击还是拖动"。
        playVoice(audioRef)
        sayLine(LINE_TEXT)
      }

      const ready = phase === 'ready' && data !== null
      const options = (data && data.options) || {}
      if (options.enabled === false) return null

      const offsetX = typeof options.offsetX === 'number' ? options.offsetX : 22
      const offsetY = typeof options.offsetY === 'number' ? options.offsetY : 18
      const corner = typeof options.corner === 'string' ? options.corner : 'bottom-right'
      const scale = typeof options.scale === 'number' ? options.scale : 190
      const baseImage = typeof options.image === 'string' && options.image !== ''
        ? options.image
        : `${BASE}/image`
      // 版本号必须拼在**最后**：宿主给的地址里已经带了它自己的 ?v=（那个不会变），
      // 所以这里用 & 接上去，而不是覆盖它。
      const imageUrl = imageStamp === ''
        ? baseImage
        : `${baseImage}${baseImage.includes('?') ? '&' : '?'}stamp=${imageStamp}`

      const signedIn = ready && data.signedIn === true
      const balance = ready && typeof data.balance === 'string' ? data.balance : null
      const symbol = ready && typeof data.symbol === 'string' ? data.symbol : ''
      const remoteError = ready ? data.error : null
      const problem = remoteError !== null && remoteError !== undefined && remoteError !== ''
        ? String(remoteError)
        : fetchError

      let label
      let dim
      if (phase === 'failed') {
        label = t.failed
        dim = true
      } else if (balance !== null) {
        label = `${symbol}${balance}`
        dim = false
      } else if (!ready) {
        label = t.loading
        dim = true
      } else if (!signedIn) {
        label = t.signedOut
        dim = true
      } else {
        label = t.unavailable
        dim = true
      }

      const rootStyle = {
        // 拖过之后用绝对坐标，没拖过就按配置的角标锚定——这样"初始右下角"与
        // "记住位置"两件事各司其职。
        ...(pos !== null
          ? { left: `${pos.x}px`, top: `${pos.y}px` }
          : {
              ...(corner.startsWith('top') ? { top: `${offsetY}px` } : { bottom: `${offsetY}px` }),
              ...(corner.endsWith('left') ? { left: `${offsetX}px` } : { right: `${offsetX}px` }),
            }),
      }

      const rows = []
      if (ready && data.source === 'account') rows.push(['来源', t.sourceAccount])
      if (ready && data.source === 'url') rows.push(['来源', t.sourceUrl])
      if (ready && data.source === 'fixed') rows.push(['来源', t.sourceFixed])
      if (ready && typeof data.bonus === 'string' && Number(data.bonus) !== 0) rows.push([t.bonus, `${symbol}${data.bonus}`])
      if (ready && data.fetchedAt !== undefined) rows.push([t.updated, agoText(data.fetchedAt, t)])

      const panel = (hover && ready && options.showDetails !== false)
        ? h('div', { className: 'pw-panel' },
            rows.map(([key, value]) => h('div', { key }, h('b', null, `${key}：`), value)),
            problem === '' ? null : h('div', { className: 'pw-err' }, problem))
        : null

      return h('div', {
        className: 'pw-root',
        ref: rootRef,
        style: rootStyle,
        onMouseEnter: () => setHover(true),
        onMouseLeave: () => setHover(false),
        // 拖动与点击的判定区是**整块挂件**（含图旁边的文字与空白），不再只认人物图；
        // 刷新按钮与明细面板在 onPointerDown 里被排除掉，它们自己处理点击。
        onPointerDown,
        onPointerMove,
        onPointerUp: endDrag,
        onPointerCancel: endDrag,
        onLostPointerCapture: endDrag,
      },
        h('style', null, STYLE),
        // 那句话浮在整块的上方：居中、不挡任何可点的东西。
        line === null ? null : h('div', { key: line.seq, className: 'pw-line' }, line.text),
        h('div', { className: 'pw-figure', style: { width: `${scale}px` } },
          h('img', {
            className: `pw-img${dragging ? ' pw-dragging' : ''}${dim ? ' pw-dim' : ''}${busy ? ' pw-busy' : ''}`,
            src: imageUrl,
            alt: '普瑞赛斯',
            draggable: false,
            // 图没加载出来时别让她变成一个空盒子
            onError: () => setFetchError('image-load-failed'),
          })),
        h('div', {
          className: 'pw-side',
          // 让数字落在**她头部的右侧**：整个挂件是横排、顶端对齐，这里再把文字栏
          // 从顶往下推 20% 的图高——她的头大约就占图的上四分之一。
          // 用比例而不是固定像素：scale 一改，文字仍然跟着头走。
          style: { marginTop: `${Math.round(scale * 0.20)}px` },
        },
          h('div', { className: 'pw-amount' + (dim ? ' pw-muted' : '') },
            // 菱形前缀：她的瞳孔是菱形。数字滚起来的时候它也一动不动地在那儿。
            h('span', { className: 'pw-diamond', 'aria-hidden': true }, '◆'),
            balance !== null ? h(RollingText, { text: label }) : label,
            h('button', {
              type: 'button',
              className: 'pw-refresh',
              title: t.refresh,
              'aria-label': t.refresh,
              'aria-busy': busy,
              disabled: busy,
              onClick: () => { void load(true) },
            }, busy ? '·' : '↻')),
          panel,
          hover ? h('div', { className: 'pw-hint' }, t.hint) : null,
        ),
      )
    }

    return {
      inject: ['slots'],
      apply(ctx) {
        // 挂在整帧最上层的浮动层里。用自己独有的 id = 新增一格，不顶掉任何条目。
        ctx.slots.inject(SLOT, () => ctx.slots.register(
          { name: SLOT, id: ROW_ID, order: 481 },
          PriestessWidget,
        ))
      },
    }
  },
})
